inline std::filesystem::path replaySaveDirectory(const ReplaySettings& s){if(!s.saveDirectory.empty())return s.saveDirectory;PWSTR path{};if(SUCCEEDED(SHGetKnownFolderPath(FOLDERID_Videos,KF_FLAG_DEFAULT,nullptr,&path))){std::filesystem::path result=std::filesystem::path(path)/L"ArcReadyPanel";CoTaskMemFree(path);return result;}throw std::runtime_error("Windows video directory unavailable");}
inline std::filesystem::path replayCacheDirectory(const ReplaySettings& s){if(!s.cacheDirectory.empty())return s.cacheDirectory;wchar_t path[32768]{};if(!GetEnvironmentVariableW(L"LOCALAPPDATA",path,32768))throw std::runtime_error("Windows cache directory unavailable");return std::filesystem::path(path)/L"ArcReadyPanel"/L"ReplayCache";}
inline std::filesystem::path replayFilename(const ReplaySettings& s){SYSTEMTIME t{};GetLocalTime(&t);wchar_t name[128]{};swprintf_s(name,L"ArcReadyPanel_%04u-%02u-%02u_%02u-%02u-%02u-%03u_%lu.mp4",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond,t.wMilliseconds,GetCurrentProcessId());return replaySaveDirectory(s)/name;}
inline std::wstring replayError(const std::exception& e){int count=MultiByteToWideChar(CP_UTF8,0,e.what(),-1,nullptr,0);if(count<=0)return L"即时回放发生错误";std::wstring value(count,0);MultiByteToWideChar(CP_UTF8,0,e.what(),-1,value.data(),count);value.pop_back();return value;}
inline uint64_t replayClock100ns(){static const uint64_t hz=[](){LARGE_INTEGER value{};QueryPerformanceFrequency(&value);return static_cast<uint64_t>(value.QuadPart);}();LARGE_INTEGER stamp{};QueryPerformanceCounter(&stamp);uint64_t ticks=static_cast<uint64_t>(stamp.QuadPart);return ticks/hz*10000000+(ticks%hz)*10000000/hz;}
inline size_t replayAudioBudget(unsigned seconds,unsigned cacheMiB){return std::min(size_t(seconds+3)*24000,size_t(cacheMiB)*1024*1024/4);}
struct ReplayStatus {bool active=false,recoverable=false;unsigned width=0,height=0;uint64_t frames=0,dropped=0;size_t bytes=0;double seconds=0;std::wstring target,error,audioDevice;};
class ReplayEngine {
 using Frame=winrt::Windows::Graphics::Capture::Direct3D11CaptureFrame;
 struct CaptureState {std::mutex mutex;std::condition_variable wake;Frame latest{nullptr};bool stopping=false,closed=false;uint64_t dropped=0;};
 std::shared_ptr<CaptureState> capture=std::make_shared<CaptureState>();ReplaySettings settings;ComPtr<IDXGIAdapter1> adapter;LUID luid;HWND window;HMONITOR monitor;std::function<void()> notify;ReplayBuffer buffer;mutable std::mutex mutex;ReplayStatus state;std::vector<uint8_t> av1Config;std::ofstream cacheStream;std::shared_ptr<ReplayCacheFile> cacheFile;uint64_t cacheOffset=0,cacheSerial=0,sessionId=0,clockBase=0,lastPts=0;bool clockReady=false;std::unique_ptr<ReplayAudio> audio;std::jthread worker;
 void publish(){if(notify)notify();}
 void append(EncodedFrame frame){
  std::lock_guard lock(mutex);if(av1Config.empty())av1Config=av1Configuration(frame.bytes);ReplayPacket packet;packet.pts=frame.pts;packet.key=frame.key;packet.size=frame.bytes.size();
  if(settings.diskCache){if(frame.key){cacheStream.close();auto file=std::make_shared<ReplayCacheFile>();file->path=replayCacheDirectory(settings)/(L"ArcReadyPanel_"+std::to_wstring(GetCurrentProcessId())+L"_"+std::to_wstring(sessionId)+L"_"+std::to_wstring(cacheSerial++)+L".agcache");std::filesystem::create_directories(file->path.parent_path());cacheStream.open(file->path,std::ios::binary|std::ios::trunc);if(!cacheStream)throw std::runtime_error("Cannot open replay cache directory");cacheFile=std::move(file);cacheOffset=0;}if(!cacheFile)return;packet.file=cacheFile;packet.offset=cacheOffset;cacheStream.write(reinterpret_cast<const char*>(frame.bytes.data()),static_cast<std::streamsize>(frame.bytes.size()));if(!cacheStream)throw std::runtime_error("Replay cache write failed");cacheOffset+=frame.bytes.size();}
  else packet.memory=std::make_shared<const std::vector<uint8_t>>(std::move(frame.bytes));buffer.append(std::move(packet));lastPts=frame.pts;++state.frames;
 }
 void runDesktop(ID3D11Device* gpu,ID3D11DeviceContext* context){
  ComPtr<IDXGIOutput> output;DXGI_OUTPUT_DESC description{};for(UINT i=0;;++i){ComPtr<IDXGIOutput> candidate;if(adapter->EnumOutputs(i,&candidate)==DXGI_ERROR_NOT_FOUND)break;replayCheck(candidate->GetDesc(&description),"desktop output");if(description.Monitor==monitor){output=std::move(candidate);break;}}if(!output)throw std::runtime_error("Desktop display is not attached to the Intel GPU");ComPtr<IDXGIOutput1> native;replayCheck(output.As(&native),"desktop duplication interface");ComPtr<IDXGIOutputDuplication> duplication;replayCheck(native->DuplicateOutput(gpu,&duplication),"desktop duplication");DXGI_OUTDUPL_DESC desc{};duplication->GetDesc(&desc);if(desc.Rotation!=DXGI_MODE_ROTATION_IDENTITY&&desc.Rotation!=DXGI_MODE_ROTATION_UNSPECIFIED)throw std::runtime_error("Rotated desktop capture is not supported yet");unsigned width=settings.width?settings.width:desc.ModeDesc.Width&~1u,height=settings.height?settings.height:desc.ModeDesc.Height&~1u;VplEncoder encoder(gpu,context,luid,width,height,settings.fps,settings.bitrate);{std::lock_guard lock(mutex);audio=std::make_unique<ReplayAudio>(settings.seconds,notify,replayAudioBudget(settings.seconds,settings.cacheMiB));state.active=true;state.width=width;state.height=height;state.target=description.DeviceName;}publish();LARGE_INTEGER hz{};QueryPerformanceFrequency(&hz);uint64_t base=0,next=0,last=0;bool first=true;
  for(;;){{std::lock_guard lock(capture->mutex);if(capture->stopping)break;}DXGI_OUTDUPL_FRAME_INFO info{};ComPtr<IDXGIResource> resource;HRESULT hr=duplication->AcquireNextFrame(500,&info,&resource);if(hr==DXGI_ERROR_WAIT_TIMEOUT)continue;replayCheck(hr,"acquire desktop frame");struct Release{IDXGIOutputDuplication* value;~Release(){value->ReleaseFrame();}} release{duplication.Get()};if(!info.LastPresentTime.QuadPart)continue;uint64_t ticks=static_cast<uint64_t>(info.LastPresentTime.QuadPart),timestamp=ticks/hz.QuadPart*10000000+(ticks%hz.QuadPart)*10000000/hz.QuadPart;if(first){base=timestamp;next=timestamp;first=false;std::lock_guard lock(mutex);clockBase=timestamp;clockReady=true;}else if(timestamp<=last||timestamp+10000000/(settings.fps*4)<next)continue;last=timestamp;next+=10000000/settings.fps;if(timestamp>next+10000000/settings.fps)next=timestamp+10000000/settings.fps;ComPtr<ID3D11Texture2D> texture;replayCheck(resource.As(&texture),"desktop texture");auto encoded=encoder.encode(texture.Get(),(timestamp-base)*9/1000);if(encoded)append(std::move(*encoded));}
  {std::lock_guard lock(mutex);cacheStream.close();cacheFile.reset();state.active=false;}
 }
 void run(){
  using namespace winrt;using namespace winrt::Windows::Graphics::Capture;using namespace winrt::Windows::Graphics::DirectX;
  bool apartment=false;Direct3D11CaptureFramePool pool{nullptr};GraphicsCaptureSession session{nullptr};GraphicsCaptureItem item{nullptr};event_token arrived{},closed{};bool subscribed=false,closeSubscribed=false;
  try{SetThreadPriority(GetCurrentThread(),THREAD_PRIORITY_BELOW_NORMAL);init_apartment(apartment_type::multi_threaded);apartment=true;if(window&&!GraphicsCaptureSession::IsSupported())throw std::runtime_error("Windows Graphics Capture unavailable");ComPtr<ID3D11Device> gpu;ComPtr<ID3D11DeviceContext> context;replayCheck(D3D11CreateDevice(adapter.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT|D3D11_CREATE_DEVICE_VIDEO_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&gpu,nullptr,&context),"create replay device");ComPtr<ID3D10Multithread> threading;replayCheck(gpu.As(&threading),"capture threading");threading->SetMultithreadProtected(TRUE);if(!window){runDesktop(gpu.Get(),context.Get());winrt::uninit_apartment();publish();return;}
   auto interop=get_activation_factory<GraphicsCaptureItem,IGraphicsCaptureItemInterop>();if(window)check_hresult(interop->CreateForWindow(window,guid_of<GraphicsCaptureItem>(),put_abi(item)));else check_hresult(interop->CreateForMonitor(monitor,guid_of<GraphicsCaptureItem>(),put_abi(item)));auto size=item.Size();unsigned width=settings.width?settings.width:static_cast<unsigned>(size.Width)&~1u,height=settings.height?settings.height:static_cast<unsigned>(size.Height)&~1u;if(!width||!height)throw std::runtime_error("Capture target has no size");VplEncoder encoder(gpu.Get(),context.Get(),luid,width,height,settings.fps,settings.bitrate);{std::lock_guard lock(mutex);audio=std::make_unique<ReplayAudio>(settings.seconds,notify,replayAudioBudget(settings.seconds,settings.cacheMiB));}
   ComPtr<IDXGIDevice> dxgi;replayCheck(gpu.As(&dxgi),"capture DXGI device");com_ptr<IInspectable> inspectable;check_hresult(CreateDirect3D11DeviceFromDXGIDevice(dxgi.Get(),inspectable.put()));auto direct=inspectable.as<winrt::Windows::Graphics::DirectX::Direct3D11::IDirect3DDevice>();pool=Direct3D11CaptureFramePool::CreateFreeThreaded(direct,DirectXPixelFormat::B8G8R8A8UIntNormalized,2,size);auto shared=capture;
   arrived=pool.FrameArrived([shared](auto const& sender,auto const&){try{auto frame=sender.TryGetNextFrame();if(!frame)return;Frame discard{nullptr};{std::lock_guard lock(shared->mutex);if(shared->stopping){frame.Close();return;}if(shared->latest){discard=std::move(shared->latest);++shared->dropped;}shared->latest=std::move(frame);}if(discard)discard.Close();shared->wake.notify_one();}catch(...){std::lock_guard lock(shared->mutex);shared->closed=true;shared->wake.notify_one();}});subscribed=true;
   closed=item.Closed([shared](auto&&,auto&&){std::lock_guard lock(shared->mutex);shared->closed=true;shared->wake.notify_one();});closeSubscribed=true;session=pool.CreateCaptureSession(item);session.IsCursorCaptureEnabled(false);// Allow one-quarter-frame scheduling jitter without requesting twice the target update rate.
   try{session.MinUpdateInterval(winrt::Windows::Foundation::TimeSpan{7500000/settings.fps});}catch(const hresult_error&){}session.StartCapture();{std::lock_guard lock(mutex);state.active=true;state.width=width;state.height=height;state.target=item.DisplayName().c_str();}publish();uint64_t base=0,last=0,next=0;bool first=true;
   for(;;){Frame frame{nullptr};{std::unique_lock lock(shared->mutex);shared->wake.wait(lock,[&]{return shared->stopping||shared->closed||shared->latest;});if(shared->stopping)break;if(shared->closed)throw std::runtime_error("Capture target closed");frame=std::move(shared->latest);}struct CloseFrame{Frame& f;~CloseFrame(){try{if(f)f.Close();}catch(...){}}} closeFrame{frame};auto content=frame.ContentSize();if(content.Width<=0||content.Height<=0)continue;if(content.Width!=size.Width||content.Height!=size.Height){size=content;pool.Recreate(direct,DirectXPixelFormat::B8G8R8A8UIntNormalized,2,size);continue;}uint64_t timestamp=static_cast<uint64_t>(frame.SystemRelativeTime().count());if(first){base=timestamp;next=timestamp;first=false;std::lock_guard lock(mutex);clockBase=timestamp;clockReady=true;}else if(timestamp<=last||timestamp+10000000/(settings.fps*4)<next)continue;last=timestamp;next+=10000000/settings.fps;if(timestamp>next+10000000/settings.fps)next=timestamp+10000000/settings.fps;
    auto access=frame.Surface().as<::Windows::Graphics::DirectX::Direct3D11::IDirect3DDxgiInterfaceAccess>();ComPtr<ID3D11Texture2D> texture;check_hresult(access->GetInterface(IID_PPV_ARGS(&texture)));auto encoded=encoder.encode(texture.Get(),(timestamp-base)*9/1000);if(encoded)append(std::move(*encoded));
   }
  }catch(const ReplayDeviceError& e){{std::lock_guard lock(mutex);state.recoverable=replayTransient(e.code);state.error=L"回放设备："+replayError(e);}publish();}catch(const winrt::hresult_error& e){{std::lock_guard lock(mutex);state.error=L"捕获失败："+std::wstring(e.message().c_str());}publish();}catch(const std::exception& e){{std::lock_guard lock(mutex);state.error=L"回放失败："+replayError(e);}publish();}
  try{if(subscribed)pool.FrameArrived(arrived);if(closeSubscribed)item.Closed(closed);if(session)session.Close();if(pool)pool.Close();}catch(...){} {std::lock_guard lock(capture->mutex);if(capture->latest){capture->latest.Close();capture->latest=nullptr;}}{std::lock_guard lock(mutex);cacheStream.close();cacheFile.reset();state.active=false;}session=nullptr;pool=nullptr;item=nullptr;if(apartment)winrt::uninit_apartment();publish();
 }
public:
 ReplayEngine(const ReplaySettings& config,IDXGIAdapter1* gpu,LUID id,HWND target,HMONITOR display,std::function<void()> callback):settings(config),adapter(gpu),luid(id),window(target),monitor(display),notify(std::move(callback)),buffer(size_t(config.cacheMiB)*1024*1024-replayAudioBudget(config.seconds,config.cacheMiB),config.seconds){LARGE_INTEGER stamp{};QueryPerformanceCounter(&stamp);sessionId=stamp.QuadPart;worker=std::jthread([this]{run();});}
 ~ReplayEngine(){{std::lock_guard lock(capture->mutex);capture->stopping=true;}capture->wake.notify_all();if(worker.joinable())worker.join();audio.reset();}
 ReplayStatus status()const{std::lock_guard lock(mutex);auto result=state;if(audio){result.audioDevice=audio->name();auto error=audio->error();if(!error.empty())result.error=L"系统声音："+error;}result.bytes=buffer.bytes()+(audio?audio->bytes():0);result.seconds=buffer.seconds();if(clockReady&&result.bytes){auto now=replayClock100ns();if(now>clockBase){auto end=(now-clockBase)*9/1000;result.seconds=std::min(double(settings.seconds),result.seconds+(end>lastPts?double(end-lastPts)/90000:0));}}{std::lock_guard captureLock(capture->mutex);result.dropped=capture->dropped;}return result;}
 ReplaySnapshot snapshot(){std::unique_lock lock(mutex);if(cacheStream.is_open()){cacheStream.flush();if(!cacheStream)throw std::runtime_error("Replay cache flush failed");}ReplaySnapshot clip{state.width,state.height,settings.fps,av1Config,buffer.snapshot()};if(clockReady&&!clip.packets.empty()){uint64_t now=replayClock100ns();clip.endPts=std::max(clip.packets.back().pts+90000/settings.fps,now>clockBase?(now-clockBase)*9/1000:0);auto first=clip.packets.front().pts;clip.endPts=std::min(clip.endPts,first+uint64_t(INT32_MAX));uint64_t start=clip.endPts>uint64_t(settings.seconds)*90000?clip.endPts-uint64_t(settings.seconds)*90000:0;size_t key=0;for(size_t i=0;i<clip.packets.size();++i)if(clip.packets[i].key&&clip.packets[i].pts<=start)key=i;if(key)clip.packets.erase(clip.packets.begin(),clip.packets.begin()+key);first=clip.packets.front().pts;clip.trimStart=start>first?start-first:0;if(audio){auto begin=clockBase+(first+clip.trimStart)*1000/9,end=clockBase+clip.endPts*1000/9;auto sound=audio.get();lock.unlock();sound->snapshot(clip,begin,end);}}return clip;}
 void configureLimits(unsigned seconds,unsigned cacheMiB){std::lock_guard lock(mutex);buffer.configure(size_t(cacheMiB)*1024*1024-replayAudioBudget(seconds,cacheMiB),seconds);settings.seconds=seconds;settings.cacheMiB=cacheMiB;if(audio)audio->configure(seconds,replayAudioBudget(seconds,cacheMiB));}
};
